import {useState} from 'react';

export const useConditionallyControlledState = <T extends unknown>(
    property?: T,
    setProperty?: (value: T) => void,
    initialState?: T,
) => {
    const state = useState<T | undefined>(property ?? initialState);

    if (setProperty !== undefined) {
        return [property, setProperty] as [T, (value: T) => void];
    }

    return state as [T, (value: T) => void];
};
